package dev.cazajefes;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class SpawnpointAndScatterTest {
 @Test public void durationParsingRejectsOverflowAndInvalidInput(){assertEquals(300,AdminArguments.seconds("5m"));assertEquals(3600,AdminArguments.seconds("1h"));assertEquals(30,AdminArguments.seconds("30s"));assertEquals(-1,AdminArguments.seconds("NaN"));assertEquals(-1,AdminArguments.seconds("9"));assertEquals(-1,AdminArguments.seconds("999999999999999h"));assertEquals(-1,AdminArguments.seconds("86401"));}
 @Test public void activeEncounterNeverRespawnsEvenAfterTimer(){assertFalse(AdminArguments.due(50000,1000,true));assertFalse(AdminArguments.due(500,1000,false));assertTrue(AdminArguments.due(1000,1000,false));assertFalse(AdminArguments.due(1000,0,false));assertTrue(AdminArguments.name("arena_1"));assertFalse(AdminArguments.name("arena.auto.enabled"));}
 @Test public void scatterHasUniqueNearbyLandingPoints(){Set<String> points=new HashSet<>();for(int i=0;i<100;i++){var p=LootScatter.at(i,100);assertTrue(Math.hypot(p.x(),p.z())<=2.7);assertTrue(points.add(p.toString()));}assertEquals(0,LootScatter.at(0,1).x(),0);}
 @Test public void modernAndLegacyPermissionsRemainCompatible(){assertTrue(AdminPermissions.allows(p->p.equals("cazajefes.admin.spawnpoint"),"rareitemhunter.admin.spawnpoint"));assertTrue(AdminPermissions.allows(p->p.equals("rareitemhunter.admin.*"),"rareitemhunter.admin.boss"));assertFalse(AdminPermissions.allows(p->p.equals("cazajefes.admin.egg"),"rareitemhunter.admin.spawnpoint"));assertTrue(AdminPermissions.allows(p->p.equals("cazajefes.admin"),"rareitemhunter.admin.reload"));}
 @Test public void administrativeCommandsDenyUnprivilegedSendersWithoutWorldAccess(){java.util.List<Object> messages=new ArrayList<>();org.bukkit.command.CommandSender sender=(org.bukkit.command.CommandSender)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{org.bukkit.command.CommandSender.class},(proxy,method,args)->{if(method.getName().equals("hasPermission"))return false;if(method.getName().equals("sendMessage")){messages.add(args[0]);return null;}if(method.getReturnType()==boolean.class)return false;return null;});var command=new CazaJefesCommand(null,null,null);for(String root:List.of("spawnpoint","punto","egg","huevo","boss","jefe","reload","recargar","eggs","get","give","rare","book","fragment","tribute","armor","weapon")){int before=messages.size();assertTrue(command.onCommand(sender,null,"ri",new String[]{root}));assertTrue(root,messages.size()>before);}assertEquals("spawnpoint",AdminArguments.root("SP"));assertEquals("boss",AdminArguments.root("jefe"));}
}
